//
// Drops the legacy `drive_type` / `owner_id` columns (superseded by `spaceId`)
// and makes `spaceId` NOT NULL.
//
// SELF-HEALING (bug B001): this migration used to assume the v1 backfill had
// already run, and simply documented it as a manual prerequisite. On a database
// that still contained v1 drive rows (`space_id IS NULL`), the NOT NULL
// constraint was rejected by Postgres and the backend crash-looped on boot.
// The migration now owns its precondition:
//   1. fold v1 rows into `type='drive'` spaces via the tested backfill module
//      (idempotent; no-op when there is no v1 data);
//   2. sweep any `drive_shares` / `drive_file_versions` rows that are still
//      NULL from their file (covers a partially-applied standalone run);
//   3. only then drop the legacy columns and enforce NOT NULL.
// The standalone batch (scripts/backfill-drive-to-spaces.ts) remains available
// for dry-run / verify inspection.
import { Kysely, sql } from 'kysely';
import { applyBackfill } from '../backfill/drive-to-spaces';

export async function up(db: Kysely<any>): Promise<void> {
  // 1. Fold v1 drive rows into drive spaces (deterministic ids, idempotent).
  await applyBackfill(db);

  // 2. Defensive sweep: inherit space_id from the file for any share/version
  //    row still NULL (e.g. left behind by a partially-applied backfill run).
  await sql`
    UPDATE drive_shares ds
    SET space_id = df.space_id
    FROM drive_files df
    WHERE ds.file_id = df.id
      AND ds.space_id IS NULL
      AND df.space_id IS NOT NULL
  `.execute(db);

  await sql`
    UPDATE drive_file_versions dv
    SET space_id = df.space_id
    FROM drive_files df
    WHERE dv.file_id = df.id
      AND dv.space_id IS NULL
      AND df.space_id IS NOT NULL
  `.execute(db);

  // 3. Drop the legacy ownership columns and enforce the space scope.
  await db.schema.alterTable('drive_folders').dropColumn('driveType').execute();
  await db.schema.alterTable('drive_folders').dropColumn('ownerId').execute();
  await db.schema.alterTable('drive_files').dropColumn('driveType').execute();
  await db.schema.alterTable('drive_files').dropColumn('ownerId').execute();

  await db.schema
    .alterTable('drive_folders')
    .alterColumn('spaceId', (col) => col.setNotNull())
    .execute();
  await db.schema
    .alterTable('drive_files')
    .alterColumn('spaceId', (col) => col.setNotNull())
    .execute();
  await db.schema
    .alterTable('drive_shares')
    .alterColumn('spaceId', (col) => col.setNotNull())
    .execute();
  await db.schema
    .alterTable('drive_file_versions')
    .alterColumn('spaceId', (col) => col.setNotNull())
    .execute();
}

